Given an array of integers arr[]. Find the length of the longest subarray such that all the elements of the subarray are smaller than or equal to the length of the subarray.Example:Input: arr[] = [1, 2, 3]Output: 3Explanation: The longest subarray is the entire array itself [1, 2, 3], which has a length of 3. All elements in the subarray are less than or equal to 3.Input: arr[] = [6, 4, 2, 5]Output: 0Explanation: There is no subarray where all elements are less than or equal to the length of the subarray. The longest subarray is empty, which has a length of 0.Try It YourselfTable of Content[Naive Approach] By Checking All The Subarray - O(n^2) Time and O(1) Space[Expected Approach] Using Stack - O(n) Time and O(n) Space[Naive Approach] By Checking All The Subarray - O(n2) Time and O(1) SpaceThe idea is to check every possible subarray, compute its maximum element, and verify if the subarray length is greater than or equal to this maximum. If valid, update the answer with the maximum length found.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int longestSubarray(vector<int>& arr) {
    int len = 0;
    int n = arr.size();

    // Check every subarray
    for (int i = 0; i < n; i++) {
        int maxi = arr[i];
        for (int j = i; j < n; j++) {

            // update max in subarray
            maxi = max(maxi, arr[j]); 
            if (j - i + 1 >= maxi) {
                len = max(len, j - i + 1);
            }
        }
    }

    return len;
}

int main() {
    vector<int> arr = {1, 2, 3};
    cout << longestSubarray(arr);
    return 0;
}


