Output3[Expected Approach] Using Stack - O(n) Time and O(n) SpaceIntuitionIf we are given an array, along with its size and maximum element, we can directly validate whether the array is valid or not (length of array >= maximum element).What if we treat every element as the maximum element and then try to find the range where that element can actually remain the maximum? So the problem reduces to: For every element arr[i], find the largest window [L..R] where arr[i] is the maximum.How to find that window?To find out the window for which an element arr[i] is the maximum:On the left side, keep moving until you find an element greater than arr[i]. The window cannot extend beyond this point, because then arr[i] would no longer be the maximum.On the right side, do the same stop as soon as you encounter an element greater than arr[i].So, the element arr[i] is the maximum in the subarray that starts just after the greater element on the left and ends just before the greater element on the right (windowLength = (NGE[i] - PGE[i] - 1)).Check validityIf windowLength >= arr[i], then it forms a valid subarray and keep track of the maximum such length.
            C++

    #include <iostream>
#include <vector>
#include <stack>
#include <algorithm>
using namespace std;

int longestSubarray(vector<int>& arr) {
    int n = arr.size();

    vector<int> nextGreater(n, n);
    vector<int> prevGreater(n, -1);

    stack<int> st;

    // Find Next Greater Element to the Right
    for (int i = 0; i < n; i++) {
        while (!st.empty() && arr[st.top()] < arr[i]) {
            nextGreater[st.top()] = i;
            st.pop();
        }
        st.push(i);
    }

    // Clear stack for next pass
    while (!st.empty()) st.pop();

    // Find Next Greater Element to the Left
    for (int i = n - 1; i >= 0; i--) {
        while (!st.empty() && arr[st.top()] < arr[i]) {
            prevGreater[st.top()] = i;
            st.pop();
        }
        st.push(i);
    }

    // Find the maximum valid subarray length
    int maxLength = 0;
    for (int i = 0; i < n; i++) {
        int windowSize = nextGreater[i] - prevGreater[i] - 1;
        if (windowSize >= arr[i]) {
            maxLength = max(maxLength, windowSize);
        }
    }

    return maxLength;
}

int main() {
    vector<int> arr = {1, 2, 3};
    cout << longestSubarray(arr);
    return 0;
}


